CREATE TABLE IF NOT EXISTS quickstart_templates (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(190) NOT NULL,
    description VARCHAR(500) NOT NULL DEFAULT '',
    category VARCHAR(50) NOT NULL DEFAULT 'Custom',
    json_structure LONGTEXT NOT NULL,
    locked TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- Seed the built-in Quickstart library (previously hardcoded in
-- src/data/quickstartTemplates.ts), locked by default so they can't be
-- deleted by accident. This migration only ever runs once per install,
-- so no additional guard against re-seeding is needed.
INSERT INTO quickstart_templates (name, description, category, json_structure, locked) VALUES ('Welcome Email', 'Onboard new users with a warm greeting and a single CTA.', 'Transactional', '{"settings":{"subject":"Welcome aboard!","preheader":"We''re so glad you joined us.","contentWidth":600,"bodyBg":"#f4f8fc","containerBg":"#ffffff","fontFamily":"Helvetica, Arial, sans-serif","textColor":"#1a2a3a","linkColor":"#2b7fe0"},"blocks":[{"id":"c0faabe1-3e9a-4f76-b788-869ebee060ce","type":"header","props":{"logoUrl":"","logoAlt":"Logo","logoWidth":140,"logoLink":"","tagline":"","taglineColor":"#ffffff","taglineSize":14,"bgColor":"#2b7fe0","align":"center","paddingY":24,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"b12af244-003b-4a4c-94eb-fdcca4a4772a","type":"heading","props":{"text":"Welcome to the team! \\ud83c\\udf89","level":1,"color":"#1a4f99","align":"center","fontFamily":"Helvetica, Arial, sans-serif","paddingY":32,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"3ed1688b-626d-4248-99cb-0304156c8ddf","type":"text","props":{"content":"Hi there,\\n\\nWe''re thrilled to have you on board. Your account is ready and you can start exploring right away. If you ever need help, our support team is here for you.","fontSize":16,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"left","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":8,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"b15cd628-ffb4-45aa-98c5-f00b5498ba50","type":"button","props":{"label":"Get Started","href":"#","bgColor":"#2b7fe0","textColor":"#ffffff","radius":8,"fullWidth":false,"width":200,"height":48,"fontSize":16,"fontFamily":"Helvetica, Arial, sans-serif","align":"center","paddingY":24,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"790044ba-7d06-4aa7-985f-3bb2bfd123b5","type":"divider","props":{"color":"#dce8f5","thickness":1,"paddingY":16,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"6701ab75-358f-49e5-b9e1-6f0027c39c7e","type":"footer","props":{"content":"\\u00a9 2026 Your Company \\u00b7 <a href=\\"#\\">Unsubscribe</a>","fontSize":12,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","bgColor":"transparent","paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}}]}', 1);
INSERT INTO quickstart_templates (name, description, category, json_structure, locked) VALUES ('Monthly Newsletter', 'A multi-section newsletter with heading, articles and a footer.', 'Newsletter', '{"settings":{"subject":"Your monthly update","preheader":"Here''s what happened this month.","contentWidth":600,"bodyBg":"#f4f8fc","containerBg":"#ffffff","fontFamily":"Helvetica, Arial, sans-serif","textColor":"#1a2a3a","linkColor":"#2b7fe0"},"blocks":[{"id":"9b0faab2-a32c-4a9d-b6b2-182fc3c70585","type":"header","props":{"logoUrl":"","logoAlt":"Logo","logoWidth":140,"logoLink":"","tagline":"Monthly Update","taglineColor":"#ffffff","taglineSize":13,"bgColor":"#1a4f99","align":"center","paddingY":24,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"1147c0c5-6561-4993-bd67-1679be305529","type":"heading","props":{"text":"What''s new this month","level":1,"color":"#1a4f99","align":"left","fontFamily":"Helvetica, Arial, sans-serif","paddingY":24,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"a4365f85-aba3-437c-9078-24793fd9fffd","type":"text","props":{"content":"Here''s a round-up of our latest news, updates, and highlights from the past month. Scroll down to catch up on everything you may have missed.","fontSize":15,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"left","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"86712228-b652-47ef-abcd-1dc9cd7a175a","type":"divider","props":{"color":"#dce8f5","thickness":1,"paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"8aa5d20f-956a-48b4-bf27-090e2fa8f9f7","type":"heading","props":{"text":"Feature Spotlight","level":2,"color":"#1a4f99","align":"left","fontFamily":"Helvetica, Arial, sans-serif","paddingY":8,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"f01ede48-af33-49d9-9dd0-c55a5460ced7","type":"text","props":{"content":"We launched a brand-new dashboard this month. The redesigned interface makes it faster to find what you need, with smarter search and personalised shortcuts.","fontSize":15,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"left","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":8,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"36c64b42-1b36-4ac3-846f-4eb21822cee7","type":"button","props":{"label":"Read More","href":"#","bgColor":"#2b7fe0","textColor":"#ffffff","radius":8,"fullWidth":false,"width":160,"height":44,"fontSize":15,"fontFamily":"Helvetica, Arial, sans-serif","align":"left","paddingY":16,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"6b6bcde8-60c8-4d63-b32d-5cca253fd707","type":"divider","props":{"color":"#dce8f5","thickness":1,"paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"22a0dc79-1323-4a18-9a4e-72dccc65bf8a","type":"footer","props":{"content":"\\u00a9 2026 Your Company \\u00b7 <a href=\\"#\\">Unsubscribe</a> \\u00b7 <a href=\\"#\\">Privacy Policy</a>","fontSize":12,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","bgColor":"transparent","paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}}]}', 1);
INSERT INTO quickstart_templates (name, description, category, json_structure, locked) VALUES ('Password Reset', 'Simple, focused password reset email with expiry notice.', 'Transactional', '{"settings":{"subject":"Reset your password","preheader":"We received a request to reset your password.","contentWidth":600,"bodyBg":"#f4f8fc","containerBg":"#ffffff","fontFamily":"Helvetica, Arial, sans-serif","textColor":"#1a2a3a","linkColor":"#2b7fe0"},"blocks":[{"id":"f168d5e0-059f-452e-ac22-b312c6a0a526","type":"header","props":{"logoUrl":"","logoAlt":"Logo","logoWidth":140,"logoLink":"","tagline":"","taglineColor":"#ffffff","taglineSize":14,"bgColor":"#2b7fe0","align":"center","paddingY":24,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"74d71cc3-b57d-4dbb-b790-f2cf64983ad5","type":"spacer","props":{"height":24,"bg":"transparent","blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"8d7338a1-d8dd-4a01-b712-d7ba10d20b05","type":"heading","props":{"text":"Reset your password","level":1,"color":"#1a4f99","align":"center","fontFamily":"Helvetica, Arial, sans-serif","paddingY":8,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"2040b3a5-1624-46ec-8a37-b97343dda5ad","type":"text","props":{"content":"We received a request to reset the password for your account. Click the button below to choose a new password. This link will expire in 24 hours.","fontSize":15,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"center","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":8,"paddingX":40,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"b4ac0236-a238-4726-9a52-608d23d476f3","type":"button","props":{"label":"Reset Password","href":"#","bgColor":"#2b7fe0","textColor":"#ffffff","radius":8,"fullWidth":false,"width":220,"height":48,"fontSize":16,"fontFamily":"Helvetica, Arial, sans-serif","align":"center","paddingY":24,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"7addab0a-ca95-4533-9f8d-618fd5986b70","type":"text","props":{"content":"If you didn''t request this, you can safely ignore this email. Your password won''t change.","fontSize":13,"lineHeight":1.6,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":8,"paddingX":40,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"54c3e1ec-56f8-459b-b5de-8835208c1a36","type":"spacer","props":{"height":16,"bg":"transparent","blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"e6853bed-c874-44f8-8fc9-af758d7dfe81","type":"footer","props":{"content":"\\u00a9 2026 Your Company \\u00b7 <a href=\\"#\\">Unsubscribe</a>","fontSize":12,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","bgColor":"transparent","paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}}]}', 1);
INSERT INTO quickstart_templates (name, description, category, json_structure, locked) VALUES ('Product Launch', 'Announce a new product with hero text, image and CTA.', 'Marketing', '{"settings":{"subject":"Introducing our latest product","preheader":"Something new is here \\u2014 and it''s built for you.","contentWidth":600,"bodyBg":"#f4f8fc","containerBg":"#ffffff","fontFamily":"Helvetica, Arial, sans-serif","textColor":"#1a2a3a","linkColor":"#2b7fe0"},"blocks":[{"id":"f5416c89-e143-4161-87a4-fc7b36df316f","type":"header","props":{"logoUrl":"","logoAlt":"Logo","logoWidth":140,"logoLink":"","tagline":"New Arrival","taglineColor":"#ffffff","taglineSize":12,"bgColor":"#1a4f99","align":"center","paddingY":24,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"35d68ee2-d207-40aa-b171-0ff02c654337","type":"image","props":{"src":"","alt":"Product image","width":600,"align":"center","link":"","fadeBottom":false,"paddingY":0,"paddingX":0,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"1e117f05-86df-4005-bf7e-dc80f10b9901","type":"heading","props":{"text":"Meet [Product Name]","level":1,"color":"#1a4f99","align":"center","fontFamily":"Helvetica, Arial, sans-serif","paddingY":28,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"d75f11f8-2079-4dba-951e-56195b50c403","type":"text","props":{"content":"We''ve been working hard on something special, and today it''s finally here. [Product Name] is designed to save you time, reduce friction and help you do your best work.","fontSize":16,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"center","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"a534e14d-7c3f-46fb-b333-84362cade10b","type":"button","props":{"label":"Discover More","href":"#","bgColor":"#2b7fe0","textColor":"#ffffff","radius":8,"fullWidth":false,"width":200,"height":48,"fontSize":16,"fontFamily":"Helvetica, Arial, sans-serif","align":"center","paddingY":28,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"ec8d1fe8-692b-4c18-be9d-7db19611c68b","type":"divider","props":{"color":"#dce8f5","thickness":1,"paddingY":8,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"368662fb-3e54-4f6c-8c66-013d9b75863e","type":"footer","props":{"content":"\\u00a9 2026 Your Company \\u00b7 <a href=\\"#\\">Unsubscribe</a>","fontSize":12,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","bgColor":"transparent","paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}}]}', 1);
INSERT INTO quickstart_templates (name, description, category, json_structure, locked) VALUES ('Order Confirmation', 'Confirm a purchase with order summary and next-steps.', 'Transactional', '{"settings":{"subject":"Your order is confirmed \\u2713","preheader":"Thanks for your order. Here are the details.","contentWidth":600,"bodyBg":"#f4f8fc","containerBg":"#ffffff","fontFamily":"Helvetica, Arial, sans-serif","textColor":"#1a2a3a","linkColor":"#2b7fe0"},"blocks":[{"id":"d5d19865-c8c2-4d04-933f-0fc9ab2b1855","type":"header","props":{"logoUrl":"","logoAlt":"Logo","logoWidth":140,"logoLink":"","tagline":"","taglineColor":"#ffffff","taglineSize":14,"bgColor":"#2b7fe0","align":"center","paddingY":24,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"08101f77-1df8-40b5-8c74-ee8c1271a6a0","type":"heading","props":{"text":"Order confirmed! \\ud83c\\udf8a","level":1,"color":"#1a4f99","align":"center","fontFamily":"Helvetica, Arial, sans-serif","paddingY":28,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"3c04a63f-bb84-4a88-a875-0dfd2f21a688","type":"text","props":{"content":"Thank you for your purchase. We''re preparing your order and will send you a shipping notification as soon as it''s on its way.","fontSize":15,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"center","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"d4cca843-3a26-4144-b415-71e3654a7387","type":"divider","props":{"color":"#dce8f5","thickness":1,"paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"7d94a5d8-5e12-4621-a50b-fc68a850877b","type":"heading","props":{"text":"Order Summary","level":2,"color":"#1a4f99","align":"left","fontFamily":"Helvetica, Arial, sans-serif","paddingY":8,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"f4ea27ad-4947-4b86-98a4-60ff13af2ff5","type":"text","props":{"content":"**Order #00000** \\u00b7 Placed on 1 Jan 2026\\n\\n[Item Name] \\u00d7 1 \\u2014 \\u00a300.00\\n\\n**Total: \\u00a300.00**","fontSize":15,"lineHeight":1.8,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"left","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"8fd216fc-1ade-434f-af38-2bda1da5f61d","type":"button","props":{"label":"View Order","href":"#","bgColor":"#2b7fe0","textColor":"#ffffff","radius":8,"fullWidth":false,"width":180,"height":44,"fontSize":15,"fontFamily":"Helvetica, Arial, sans-serif","align":"left","paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"97b5585e-413e-41f7-9ec8-2b67fa30d2da","type":"divider","props":{"color":"#dce8f5","thickness":1,"paddingY":8,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"b9cadb04-2907-47d8-a71f-e3efdd5ed583","type":"footer","props":{"content":"\\u00a9 2026 Your Company \\u00b7 <a href=\\"#\\">Unsubscribe</a>","fontSize":12,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","bgColor":"transparent","paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}}]}', 1);
INSERT INTO quickstart_templates (name, description, category, json_structure, locked) VALUES ('Event Invitation', 'Invite recipients to an event with date, details and RSVP.', 'Marketing', '{"settings":{"subject":"You''re invited!","preheader":"Join us for a special event.","contentWidth":600,"bodyBg":"#f4f8fc","containerBg":"#ffffff","fontFamily":"Helvetica, Arial, sans-serif","textColor":"#1a2a3a","linkColor":"#2b7fe0"},"blocks":[{"id":"3cd4941e-65f3-4258-83f9-76d5945e3e7e","type":"header","props":{"logoUrl":"","logoAlt":"Logo","logoWidth":140,"logoLink":"","tagline":"You''re Invited","taglineColor":"#ffffff","taglineSize":13,"bgColor":"#1a4f99","align":"center","paddingY":24,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"21227a25-d9b2-4e0f-b55b-b3b9652636c2","type":"heading","props":{"text":"[Event Name]","level":1,"color":"#1a4f99","align":"center","fontFamily":"Helvetica, Arial, sans-serif","paddingY":28,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"3b24bce3-f70b-4ca9-bc7a-e1bd5a3ca405","type":"text","props":{"content":"\\ud83d\\udcc5 **Date:** Saturday, 1 January 2026\\n\\ud83d\\udccd **Location:** 123 Example Street, London\\n\\u23f0 **Time:** 6:00 PM \\u2014 10:00 PM","fontSize":15,"lineHeight":1.9,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"center","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"0918b151-7f12-4071-a9ad-12791b41aa58","type":"divider","props":{"color":"#dce8f5","thickness":1,"paddingY":16,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"f56561bf-b612-4bc2-a8cc-d4ef4eb27aae","type":"text","props":{"content":"We''d love to see you there. Join us for an evening of [brief description of event]. Light refreshments will be provided.","fontSize":15,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"center","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"605e9ab9-8745-466a-93fb-d38c880f7d7d","type":"button","props":{"label":"RSVP Now","href":"#","bgColor":"#2b7fe0","textColor":"#ffffff","radius":8,"fullWidth":false,"width":180,"height":48,"fontSize":16,"fontFamily":"Helvetica, Arial, sans-serif","align":"center","paddingY":28,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"907f48b0-512f-4932-8fb0-82de8cee254b","type":"footer","props":{"content":"\\u00a9 2026 Your Company \\u00b7 <a href=\\"#\\">Unsubscribe</a>","fontSize":12,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","bgColor":"transparent","paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}}]}', 1);
INSERT INTO quickstart_templates (name, description, category, json_structure, locked) VALUES ('Promotional Offer', 'Discount or special offer email with bold hero and urgency copy.', 'Marketing', '{"settings":{"subject":"Exclusive offer just for you \\ud83c\\udf81","preheader":"Don''t miss out \\u2014 limited time only.","contentWidth":600,"bodyBg":"#f4f8fc","containerBg":"#ffffff","fontFamily":"Helvetica, Arial, sans-serif","textColor":"#1a2a3a","linkColor":"#2b7fe0"},"blocks":[{"id":"dfc6d9d8-fc22-44e9-9cbe-fcf1732d555e","type":"header","props":{"logoUrl":"","logoAlt":"Logo","logoWidth":140,"logoLink":"","tagline":"Limited Time Offer","taglineColor":"#ffffff","taglineSize":12,"bgColor":"#2b7fe0","align":"center","paddingY":24,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"a260ae70-80b2-4060-82dc-12d6b4ab1ad4","type":"heading","props":{"text":"20% off everything","level":1,"color":"#1a4f99","align":"center","fontFamily":"Helvetica, Arial, sans-serif","paddingY":32,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"a6ced8e6-f15e-46ef-8ddc-7e7e76163df1","type":"text","props":{"content":"For this week only, enjoy 20% off your entire order. Use code **ARCTIC20** at checkout. Offer ends Sunday at midnight.","fontSize":16,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"center","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"bde1a2de-2163-483d-99c3-1f63631cabc6","type":"button","props":{"label":"Shop Now","href":"#","bgColor":"#2b7fe0","textColor":"#ffffff","radius":8,"fullWidth":false,"width":200,"height":52,"fontSize":17,"fontFamily":"Helvetica, Arial, sans-serif","align":"center","paddingY":28,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"9947ef6a-2232-48ee-b5d4-3334908cb26f","type":"text","props":{"content":"Terms and conditions apply. Offer valid on full-price items only.","fontSize":12,"lineHeight":1.5,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":4,"paddingX":40,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"a3b72ee8-55f0-49f2-b98a-16360b5ef4e2","type":"divider","props":{"color":"#dce8f5","thickness":1,"paddingY":12,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"fe92c1c6-1eab-4992-84d7-d85fa6ac048f","type":"footer","props":{"content":"\\u00a9 2026 Your Company \\u00b7 <a href=\\"#\\">Unsubscribe</a>","fontSize":12,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","bgColor":"transparent","paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}}]}', 1);
INSERT INTO quickstart_templates (name, description, category, json_structure, locked) VALUES ('Account Notification', 'Alert users to an important change or activity on their account.', 'Transactional', '{"settings":{"subject":"Important account notice","preheader":"Action may be required on your account.","contentWidth":600,"bodyBg":"#f4f8fc","containerBg":"#ffffff","fontFamily":"Helvetica, Arial, sans-serif","textColor":"#1a2a3a","linkColor":"#2b7fe0"},"blocks":[{"id":"219bdedd-f626-42fb-8dab-f4964b10f023","type":"header","props":{"logoUrl":"","logoAlt":"Logo","logoWidth":140,"logoLink":"","tagline":"","taglineColor":"#ffffff","taglineSize":14,"bgColor":"#2b7fe0","align":"center","paddingY":24,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"87a3a888-650c-4223-bf75-e33b7b8deb69","type":"heading","props":{"text":"Account Notice","level":1,"color":"#1a4f99","align":"center","fontFamily":"Helvetica, Arial, sans-serif","paddingY":28,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"b089d9bc-6bf2-40c3-b091-11bb200d9b83","type":"text","props":{"content":"We noticed some activity on your account that you should be aware of. Here are the details:","fontSize":15,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"left","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"45a346a1-de5e-4ca8-bd20-75317f6137af","type":"text","props":{"content":"**Action:** [Description of activity]\\n**Date:** 1 January 2026, 12:00 PM\\n**IP Address:** 000.000.000.000","fontSize":14,"lineHeight":1.9,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"left","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":12,"paddingX":32,"blockBg":"#f4f8fc","blockRadius":8,"widthPct":100}},{"id":"50b52335-5d68-4a77-9a56-39c9f0706b75","type":"text","props":{"content":"If th