INSERT INTO quickstart_templates (name, description, category, json_structure, locked) VALUES ('Re-engagement', 'Win back inactive subscribers with a friendly nudge.', 'Marketing', '{"settings":{"subject":"We miss you \\ud83d\\udc99","preheader":"It''s been a while \\u2014 come back and see what''s new.","contentWidth":600,"bodyBg":"#f4f8fc","containerBg":"#ffffff","fontFamily":"Helvetica, Arial, sans-serif","textColor":"#1a2a3a","linkColor":"#2b7fe0"},"blocks":[{"id":"7f9f523b-f4a3-47bd-978b-7bcb171959b5","type":"header","props":{"logoUrl":"","logoAlt":"Logo","logoWidth":140,"logoLink":"","tagline":"","taglineColor":"#ffffff","taglineSize":14,"bgColor":"#1a4f99","align":"center","paddingY":24,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"f85cd509-6d85-4eac-984a-25839673a6ea","type":"heading","props":{"text":"We miss you \\ud83d\\udc99","level":1,"color":"#1a4f99","align":"center","fontFamily":"Helvetica, Arial, sans-serif","paddingY":28,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"9e410558-9b3a-49cd-9b7d-727365ab8a07","type":"text","props":{"content":"It''s been a while since we last saw you, and we wanted to check in. A lot has changed since your last visit \\u2014 here''s what you''ve been missing:","fontSize":16,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"center","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"9d5bec6d-1911-419b-acab-dce911707088","type":"divider","props":{"color":"#dce8f5","thickness":1,"paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"3e79a0ba-3a80-40d0-9445-2c452e92d017","type":"text","props":{"content":"\\u2728 New features you''ll love\\n\\ud83d\\udcca Improved reports and insights\\n\\ud83e\\udd1d A community ready to welcome you back","fontSize":15,"lineHeight":2,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"left","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"5fa359df-afed-42dd-aad4-3869a24ecb64","type":"button","props":{"label":"Come Back","href":"#","bgColor":"#2b7fe0","textColor":"#ffffff","radius":8,"fullWidth":false,"width":180,"height":48,"fontSize":16,"fontFamily":"Helvetica, Arial, sans-serif","align":"center","paddingY":28,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"1125ef79-b1fa-4856-ac00-d66f51858d0b","type":"footer","props":{"content":"\\u00a9 2026 Your Company \\u00b7 <a href=\\"#\\">Unsubscribe</a>","fontSize":12,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","bgColor":"transparent","paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}}]}', 1);
INSERT INTO quickstart_templates (name, description, category, json_structure, locked) VALUES ('Team Announcement', 'Internal or external announcement with two-column layout.', 'Internal', '{"settings":{"subject":"An important announcement","preheader":"We have some exciting news to share.","contentWidth":600,"bodyBg":"#f4f8fc","containerBg":"#ffffff","fontFamily":"Helvetica, Arial, sans-serif","textColor":"#1a2a3a","linkColor":"#2b7fe0"},"blocks":[{"id":"037c8c89-e48d-4f0c-ac10-563f6bb03b06","type":"header","props":{"logoUrl":"","logoAlt":"Logo","logoWidth":140,"logoLink":"","tagline":"Announcement","taglineColor":"#ffffff","taglineSize":12,"bgColor":"#2b7fe0","align":"center","paddingY":24,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"7ecacc4c-8f67-4a3e-9e79-585be137b23a","type":"heading","props":{"text":"Big news from [Company]","level":1,"color":"#1a4f99","align":"center","fontFamily":"Helvetica, Arial, sans-serif","paddingY":28,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"7ee6f231-43e5-495a-ab36-f79bc1244277","type":"text","props":{"content":"We''re excited to share some important news with you. After months of hard work and planning, we''re ready to announce [the news].","fontSize":16,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"center","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":0,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"b9972468-6eb8-4fa8-b212-7072458efbde","type":"divider","props":{"color":"#dce8f5","thickness":1,"paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"e87ccbad-0035-40df-8ccb-32070af4b635","type":"twocol","props":{"ratio":"50-50","gap":16,"paddingY":0,"paddingX":24,"blockBg":"transparent","blockRadius":0,"widthPct":100},"columns":[[{"id":"5e97886f-9ec7-4501-ac34-fba7651e41af","type":"heading","props":{"text":"What this means","level":3,"color":"#1a4f99","align":"left","fontFamily":"Helvetica, Arial, sans-serif","paddingY":8,"paddingX":8,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"258da7a6-0415-4fec-b14d-73bff760f204","type":"text","props":{"content":"This change will help us serve you better and grow in the direction we all believe in.","fontSize":14,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"left","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":4,"paddingX":8,"blockBg":"transparent","blockRadius":0,"widthPct":100}}],[{"id":"5f50b214-e9f9-48f3-b3ee-88566789fec8","type":"heading","props":{"text":"What happens next","level":3,"color":"#1a4f99","align":"left","fontFamily":"Helvetica, Arial, sans-serif","paddingY":8,"paddingX":8,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"cc5bf560-d589-42b9-9d6e-699c1020596b","type":"text","props":{"content":"We''ll be in touch with more details over the coming weeks. In the meantime, feel free to reach out with any questions.","fontSize":14,"lineHeight":1.7,"fontFamily":"Helvetica, Arial, sans-serif","color":"#1a2a3a","align":"left","linkColor":"#2b7fe0","paragraphSpacing":12,"listItemSpacing":4,"paddingY":4,"paddingX":8,"blockBg":"transparent","blockRadius":0,"widthPct":100}}]]},{"id":"ed90080d-dddc-4a45-bfb9-74e3ca6e2a4e","type":"button","props":{"label":"Learn More","href":"#","bgColor":"#2b7fe0","textColor":"#ffffff","radius":8,"fullWidth":false,"width":180,"height":44,"fontSize":15,"fontFamily":"Helvetica, Arial, sans-serif","align":"center","paddingY":24,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}},{"id":"a32168f0-e630-4c18-853e-b3d6947b1fdb","type":"footer","props":{"content":"\\u00a9 2026 Your Company \\u00b7 <a href=\\"#\\">Unsubscribe</a>","fontSize":12,"fontFamily":"Helvetica, Arial, sans-serif","color":"#5c7793","align":"center","bgColor":"transparent","paddingY":20,"paddingX":32,"blockBg":"transparent","blockRadius":0,"widthPct":100}}]}', 1);
